#include <stdio.h>
#include <stdlib.h>

#define QUEUE_SIZE 5

int head = 0;
int count = 0;
long items[QUEUE_SIZE];

void enqueue(long item) {
    if (count < QUEUE_SIZE) {
        items[(head + count) % QUEUE_SIZE] = item;
        count++;
        printf("ENQ %ld\n", item);
    } else {
        printf("FULL\n");
    }
}

void dequeue() {
    if (count > 0) {
        long item = items[head];
        head = (head + 1) % QUEUE_SIZE;
        count--;
        printf("DEQ %ld\n", item);
    } else {
        printf("EMPTY\n");
    }
}

void print_front() {
    if (count > 0) {
        printf("FRONT %ld\n", items[head]);
    } else {
        printf("EMPTY\n");
    }
}

int main(int argc, char *argv[]) {
    for (int i = 1; i < argc; i++) {
        char *cmd = argv[i];
        if (cmd[0] == 'E') {
            long item = strtol(cmd + 1, NULL, 10);
            enqueue(item);
        } else if (cmd[0] == 'D') {
            dequeue();
        } else if (cmd[0] == 'F') {
            print_front();
        } else {
            printf("NOOP\n");
        }
    }
    return 0;
}
